#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ships_featured_adapter_icons() {
        for id in ["bible-app", "bible-gateway", "logos", "got-questions"] {
            let bytes = png(id).unwrap_or_else(|| panic!("missing icon for {id}"));
            assert!(bytes.len() > 50 && bytes[0] == 0x89 && bytes[1..4] == *b"PNG", "{id} should be PNG");
        }
    }

    #[test]
    fn unknown_adapter_has_no_icon() {
        assert!(png("not-a-real-adapter").is_none());
    }
}
